/**
 * THE RELAY HALF OF THE CONDENSE PARITY CONTRACT.
 *
 * `src/lib/condense.parity.json` is GENERATED by the desktop
 * (`local-operator-ui/scripts/generate-condense-parity.mjs`) from the desktop's own
 * shipped model, and copied here byte for byte with its sha256 pinned in
 * `parity-sources.json`. This file replays every case through this surface's port
 * (`condense-rows.ts` -> `condense-fold.ts` -> `condense-plan.ts`) and compares
 * DECISIONS, never words: ids, segment keys, structured count units
 * (`{key, count}`), label KINDS, the elected answer, the visible-row partition,
 * the head-cut flags. Each surface owns its own English and its own locale, so an
 * English string in this contract would either forbid the phone its own words or
 * drift in silence - the defect the quiet-group fixture's nine-day divergence was.
 *
 * WHY THE CASES ARE NOT AUTHORED HERE. A fixture both sides hand-write is two
 * opinions with a shared filename. The desktop's generator runs the desktop's
 * model; this test runs ours. A port that drifts fails HERE, in the tree that
 * drifted, rather than on the phone.
 *
 * THE SKIP IS ONE FAMILY, MEASURED (architect §5; corrected in round 2, C1-m5).
 * `Z` / `R` - the quiet `no_reply` call, settled and running - cannot cross this
 * wire at all: the relay never mints that row (quiet-turn design §5, S1). WHAT
 * THAT MEANS HERE is that the turn does NOT SPLIT. A quiet close ends the turn on
 * the desktop, so the next prompt opens a new run; with no such row, both prompts
 * stay in ONE run, whose earlier exchange condenses when the merged run settles.
 * The label is the run's own - `Steered` belongs to a user row inside a run, and a
 * user row is pinned, so no bar changes its words. `the quiet-closed fallback the
 * skip-list names` asserts the split (2 runs on the desktop shape, 1 here).
 * And the closed-notice and terminal-notice tokens DO replay, because C1's
 * `terminal` flag is what makes a notice `complete` on this wire (`K` closed/info,
 * `M` terminal/error, `O` a plain notice): the relay's `:stop` notice, a live
 * `AgentEndEvent.error` notice and a session incident all carry it.
 *
 * The test asserts the skipped set is EXACTLY the cases matching those tokens, so
 * a desktop case can never fall into a silent gap - the same discipline
 * `quiet-groups.test.ts` uses for its two unexpressible cases.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { buildRows, ledgerName } from "./condense-rows";
import {
	FOLD_MIN_ACTIONS,
	foldRuns,
	latchFoldedRuns,
	receiptFoldUnits,
	workedSecondsOf,
} from "./condense-fold";
import { collapsePlan } from "./condense-plan";
import { isQuietTurnCall } from "./condense-segments";
import { isFailedResult, isInternalReceipt } from "./condense-predicates";
import { toCondenseRecords, rowKey, type CondenseRecord } from "./condense-records";
import type { TranscriptEntry } from "../types";
import type { Row } from "./condense-rows";

const HERE = __dirname;

/** One case's decision set, as the desktop's generator serialises it. */
interface Case {
	tokens: string;
	options: string;
	expected: unknown;
}

const FIXTURE_BYTES = readFileSync(join(HERE, "condense.parity.json"), "utf8");
const FIXTURE = JSON.parse(FIXTURE_BYTES) as {
	desktop: { commit: string; permutations: string[] };
	cases: Case[];
};
/**
 * The pin for each copied fixture. `sha256` is the exact bytes beside this file;
 * `sourceHash` is the desktop MODEL SOURCE hash those bytes came from (see
 * `parity-sources.json`). There is deliberately no commit field: a commit cannot
 * contain its own SHA, and one recorded at generation time names a tree that need
 * not have produced these bytes (C0-B1).
 */
const SOURCES = JSON.parse(readFileSync(join(HERE, "parity-sources.json"), "utf8")) as Record<
	string,
	{ sha256: string; sourceHash?: string }
>;

/** The token shapes this wire cannot carry (see the header). */
const NOT_EXPRESSIBLE_TOKENS = new Set(["Z", "R"]);

/** The same two tokens, for the independent derivation above. */
const QUIET_TOKENS = new Set(["R", "Z"]);

const optionOf = (token: string) => {
	const [mode, live, older] = token.split("|");
	return { mode: mode as "by-turn" | "by-response", live: live === "live", olderRowsExist: older === "older" };
};

/*
 * THE TOKEN GRAMMAR, ported from the desktop's
 * `scripts/fixtures/record-tokens.mjs`. These are DESKTOP-vocabulary records, not
 * wire entries: the wire-to-record mapping is `condense-records.ts`, and it is
 * exercised by the mapping tests below rather than by the replay, because the
 * fixture's shapes are what the desktop's model can express, not what a journal
 * happened to contain.
 */
const TS = 1_000_000;

const custom = (id: string, i: number, customType: string, level = "info"): CondenseRecord => ({
	kind: "custom",
	id,
	ts: TS + i,
	text: "t",
	customType,
	level,
});

const RECORDS: Record<string, (id: string, i: number) => CondenseRecord> = {
	U: (id, i) => ({ kind: "user", id, ts: TS + i, text: "hi" }),
	T: (id, i) => ({
		kind: "tool",
		id,
		ts: TS + i,
		toolName: "bash",
		phase: "done",
		isError: false,
		stopped: false,
		neverSent: false,
		notRunReason: null,
		durationS: null,
	}),
	N: (id, i) => ({
		kind: "assistant",
		id,
		ts: TS + i,
		text: "text",
		streaming: false,
		callsTools: true,
	}),
	F: (id, i) => ({ kind: "assistant", id, ts: TS + i, text: "text", streaming: false }),
	A: (id, i) => ({
		kind: "assistant",
		id,
		ts: TS + i,
		text: "text",
		streaming: false,
		stopReason: "stop",
	}),
	L: (id, i) => ({
		kind: "assistant",
		id,
		ts: TS + i,
		text: "text",
		streaming: false,
		stopReason: "toolUse",
		callsTools: true,
	}),
	S: (id, i) => ({ kind: "assistant", id, ts: TS + i, text: "text", streaming: true }),
	E: (id, i) => ({
		kind: "assistant",
		id,
		ts: TS + i,
		text: "",
		streaming: false,
		callsTools: true,
	}),
	W: (id, i) => ({ kind: "wake", id, ts: TS + i, text: "wake" }),
	P: (id, i) => ({
		kind: "peer",
		id,
		ts: TS + i,
		body: "peer",
		sender: { pid: "", conversationName: "", cwd: "", sessionId: "", modelLabel: "" },
	}),
	J: (id, i) => custom(id, i, "job_result"),
	H: (id, i) => custom(id, i, "hub_message"),
	X: (id, i) => custom(id, i, "monitor_prompt"),
	Q: (id, i) => custom(id, i, "session_mcp_unavailable"),
	I: (id, i) => custom(id, i, "session_incident", "error"),
	Z: (id, i) => ({
		kind: "tool",
		id,
		ts: TS + i,
		toolName: "no_reply",
		phase: "done",
		isError: false,
		stopped: false,
		neverSent: false,
		notRunReason: null,
		durationS: null,
	}),
	R: (id, i) => ({
		kind: "tool",
		id,
		ts: TS + i,
		toolName: "no_reply",
		phase: "running",
		isError: false,
		stopped: false,
		neverSent: false,
		notRunReason: null,
		durationS: null,
	}),
	M: (id, i) => ({
		kind: "notice",
		id,
		ts: TS + i,
		text: "Stopped with an error",
		level: "error",
		complete: true,
	}),
	K: (id, i) => ({
		kind: "notice",
		id,
		ts: TS + i,
		text: "Completed",
		level: "info",
		complete: true,
	}),
	O: (id, i) => ({ kind: "notice", id, ts: TS + i, text: "n", level: "info", complete: false }),
	C: (id, i) => ({ kind: "compaction", id, ts: TS + i, text: "Context", before: null }),
	/*
	 * THE DESKTOP'S TOOL-VARIETY TOKENS, mirrored from
	 * `scripts/fixtures/record-tokens.mjs`. Without them the corpus pinned one
	 * `kind:` key, so the count line's class ordering, the failure tally and `Took`
	 * were not compared at all (round 1, C0-M2).
	 */
	Rd: (id, i) => foldTool(id, i, "read"),
	Wr: (id, i) => foldTool(id, i, "write"),
	Sr: (id, i) => foldTool(id, i, "web_fetch"),
	Wb: (id, i) => foldTool(id, i, "web_search"),
	Mc: (id, i) => foldTool(id, i, "mcp__datadog_search_datadog_metrics"),
	Ag: (id, i) => foldTool(id, i, "task"),
	Py: (id, i) => foldTool(id, i, "eval"),
	Ak: (id, i) => foldTool(id, i, "agent"),
	Td: (id, i) => foldTool(id, i, "todo"),
	Fa: (id, i) => ({ ...foldTool(id, i, "bash"), isError: true }),
	Du: (id, i) => ({ ...foldTool(id, i, "bash"), durationS: 7 }),
};

/** A settled tool record, as the desktop's token grammar builds them. */
const foldTool = (id: string, i: number, toolName: string): CondenseRecord => ({
	kind: "tool",
	id,
	ts: TS + i,
	toolName,
	phase: "done",
	isError: false,
	stopped: false,
	neverSent: false,
	notRunReason: null,
	durationS: null,
});

const seq = (spec: string): CondenseRecord[] =>
	spec
		.trim()
		.split(/\s+/)
		.map((token, index) => RECORDS[token](`${token}${index}`, index));

/**
 * The production fold wiring, ported from `canonical-transcript.tsx`'s call site.
 * These are inputs to the model, not decisions of it, so the relay passes the same
 * ones the desktop's generator does - `summaryOf` and `opOf` are the live clause's
 * WORDS (surface copy) and the relay's own row supplies them, so both stay "".
 */
const foldOptions = (liveTurn: boolean, latchedFoldIds: ReadonlySet<string>) => ({
	nameOf: (row: Row) => ledgerName(row.record),
	durationOf: workedSecondsOf,
	summaryOf: () => "",
	opOf: () => "",
	failedOf: (row: Row) =>
		row.record.kind === "tool" && isFailedResult(row.record.isError, undefined),
	runningOf: (row: Row) => row.record.kind === "tool" && row.record.phase !== "done",
	executingOf: (row: Row) => row.record.kind === "tool" && row.record.phase === "running",
	startedAtOf: () => null,
	endedAtOf: () => null,
	isFoldable: (row: Row) => row.record.kind === "tool" && !isQuietTurnCall(row.record),
	isReceipt: (row: Row) => isInternalReceipt(row.record),
	receiptSummaryOf: (rows: Row[]) => receiptFoldUnits(rows),
	liveTurn,
	latchedFoldIds,
});

const countUnits = (segments: { key: string; count: number }[]) =>
	segments.map((segment) => ({ key: segment.key, count: segment.count }));

const labelToken = (kind: { kind: string; family?: string } | null): string | null =>
	kind === null ? null : kind.kind === "group" ? `group:${kind.family}` : kind.kind;

/** What THIS surface decides for one record list, in the fixture's own shape. */
function decide(records: CondenseRecord[], optionToken: string) {
	const options = optionOf(optionToken);
	const rows = buildRows(records, []);
	const groups = foldRuns(rows, foldOptions(false, new Set()));
	const plan = collapsePlan(rows, {
		live: options.live,
		mode: options.mode,
		olderRowsExist: options.olderRowsExist,
	});
	const hidden = new Set<string>();
	for (const run of plan.runs)
		for (const segment of run.segments)
			if (segment.collapsed) for (const row of segment.rows) hidden.add(row.record.id);
	return {
		visibleIds: rows.map((row) => row.record.id).filter((id) => !hidden.has(id)),
		groups: groups
			.filter((group) => group.kind === "run")
			.map((group) => ({
				id: group.id,
				rowIds: group.rows.map((row) => row.record.id),
				countUnits: countUnits(group.summary.countUnits),
				failedCount: group.failedCount,
				live: group.live !== null,
			})),
		runs: plan.runs.map((run) => ({
			key: run.key,
			answerId: run.answerId,
			collapses: run.collapses,
			recordIds: run.recordIds,
			facts: {
				actions: run.facts.actions,
				partial: run.facts.partial,
				durationS: run.facts.durationS,
				failed: run.facts.failed,
				firstFailedId: run.facts.firstFailedId,
				countUnits: countUnits(run.facts.countUnits),
			},
			segments: run.segments.map((segment) => ({
				key: segment.key,
				rowIds: segment.rows.map((row) => row.record.id),
				labelKind: labelToken(segment.labelKind),
				collapsed: segment.collapsed,
				completed: segment.completed,
				afterAnswer: segment.afterAnswer,
				group: segment.facts.group === null ? null : segment.facts.group.family,
				groupCount: segment.facts.group === null ? null : segment.facts.group.count,
				facts: {
					actions: segment.facts.actions,
					partial: segment.facts.partial,
					durationS: segment.facts.durationS,
					failed: segment.facts.failed,
					countUnits: countUnits(segment.facts.countUnits),
				},
			})),
		})),
	};
}

const skipped = (entry: Case) =>
	entry.tokens
		.trim()
		.split(/\s+/)
		.some((token) => NOT_EXPRESSIBLE_TOKENS.has(token));

describe("the condense parity fixture", () => {
	it("is the copy the manifest pins, byte for byte", () => {
		const digest = createHash("sha256").update(FIXTURE_BYTES).digest("hex");
		expect(SOURCES["condense.parity.json"].sha256).toBe(digest);
		/*
		 * THE PIN IS THE MODEL SOURCE HASH, not a commit (C0-B1 on the desktop side:
		 * a commit cannot contain its own SHA, and one that did may name a tree that
		 * never produced these bytes). The desktop's generator hashes the model files
		 * it bundled; this manifest records that hash, so the pair is comparable
		 * without a git lookup on either side. `scripts/check-condense-parity-latest.mjs`
		 * is what compares it against the desktop's OWN manifest when that checkout is
		 * present.
		 */
		expect(SOURCES["condense.parity.json"].sourceHash).toBe(
			(FIXTURE.desktop as { sourceHash?: string }).sourceHash,
		);
		expect(SOURCES["condense.parity.json"].sourceHash).toMatch(/^[0-9a-f]{64}$/);
	});

	it("skips exactly the cases this wire cannot express, and no others", () => {
		/*
		 * AN INDEPENDENT DERIVATION, not the same expression twice. The left side
		 * re-derives "unexpressible" from the TOKENS the way the wire does - a case
		 * is skipped iff it carries the quiet call the projector never mints - and
		 * the right side is the file's own `skipped()`. Round 1 compared two
		 * identical expressions, which cannot fail.
		 */
		const fromTokens = FIXTURE.cases.filter((entry) =>
			entry.tokens
				.trim()
				.split(/\s+/)
				.some((token) => QUIET_TOKENS.has(token)),
		);
		const fromHelper = FIXTURE.cases.filter(skipped);
		expect(fromHelper.map((entry) => entry.tokens)).toEqual(
			fromTokens.map((entry) => entry.tokens),
		);
		/*
		 * AND THE SIZE IS PINNED, so a desktop change that adds a wall of quiet
		 * cases shows up as a diff in review instead of quietly shrinking what this
		 * suite proves. `-27` is read from the corpus this copy pins.
		 */
		expect(fromHelper.length).toBe(27);
		/* Every skip carries the quiet pair, and none is skipped for another reason:
		 * an unbuilt token would throw inside `seq`, never be filtered quietly. */
		for (const entry of fromHelper) {
			const tokens = entry.tokens.split(/\s+/);
			expect(tokens.some((token) => QUIET_TOKENS.has(token))).toBe(true);
		}
	});

	for (const entry of FIXTURE.cases.filter((candidate) => !skipped(candidate)))
		it(`${entry.tokens} [${entry.options}]`, () => {
			expect(decide(seq(entry.tokens), entry.options)).toEqual(entry.expected);
		});

	it("the fold constants match the ones the fixture was generated with", () => {
		/* A quiet proof that the ported constants are the desktop's: the fixture's own
		 * corpus does not state them, and a port that flipped a threshold would show
		 * up as hundreds of case failures rather than one readable line. */
		expect(FOLD_MIN_ACTIONS).toBe(3);
	});

	it("the latch keeps a group the reader has seen folded", () => {
		const rows = buildRows(seq("T T T A"), []);
		const groups = foldRuns(rows, foldOptions(true, new Set()));
		const held = { has: (id: string) => rows.some((row) => row.record.id === id) };
		const latched = latchFoldedRuns(new Set<string>(), held, groups);
		expect([...latched].sort()).toEqual(["T0", "T1", "T2"]);
	});
});

describe("the wire-to-record mapping (the one relay-specific file)", () => {
	/*
	 * THE REPLAY ABOVE DRIVES DESKTOP-VOCABULARY RECORDS, deliberately: it asks the
	 * ported MODEL the same question the desktop's generator asked. These tests ask
	 * the other question - does this wire's row arrive at the model as the same
	 * record the desktop would have built? - and they are the only place the four
	 * new wire fields are exercised end to end.
	 */
	const entry = (over: Partial<TranscriptEntry>): TranscriptEntry =>
		({
			id: "e1",
			kind: "assistant",
			text: "hi",
			tool_call_id: "",
			tool_name: "",
			tool_state: "done",
			summary: "",
			intent: "",
			diff_added: 0,
			diff_removed: 0,
			elapsed_s: 0,
			error: "",
			details: {},
			final: true,
			...over,
		}) as TranscriptEntry;

	it("carries the assistant phase and the calls fact", () => {
		const [record] = toCondenseRecords([
			entry({ stop_reason: "toolUse", calls_tools: true, final: false }),
		]);
		expect(record).toMatchObject({
			kind: "assistant",
			stopReason: "toolUse",
			callsTools: true,
			streaming: true,
		});
	});

	it("an absent phase reads as unknown, never as a settled stop", () => {
		const [record] = toCondenseRecords([entry({})]);
		expect(record).toMatchObject({ stopReason: null, callsTools: false });
	});

	it("a receipt notice becomes the custom row the fold groups by", () => {
		const records = toCondenseRecords([
			entry({ id: "n1", kind: "notice", text: "job done", custom_type: "job_result" }),
		]);
		expect(records[0]).toMatchObject({ kind: "custom", customType: "job_result" });
	});

	it("a terminal notice is COMPLETE, and a plain one is not", () => {
		const records = toCondenseRecords([
			entry({ id: "n1", kind: "notice", text: "Stopped", terminal: true }),
			entry({ id: "n2", kind: "notice", text: "note" }),
		]);
		expect(records[0]).toMatchObject({ kind: "notice", complete: true });
		expect(records[1]).toMatchObject({ kind: "notice", complete: false });
	});

	it("a live and a replayed tool row share one identity", () => {
		expect(rowKey({ id: "tc-abc", kind: "tool", tool_call_id: "abc" })).toBe("call:abc");
		expect(rowKey({ id: "m1:abc", kind: "tool", tool_call_id: "abc" })).toBe("call:abc");
		expect(rowKey({ id: "u1", kind: "user", tool_call_id: "" })).toBe("u1");
	});

	it("two kinds the wire carries map to their arms", () => {
		const records = toCondenseRecords([entry({ kind: "reasoning" }), entry({ id: "x", kind: "steer" })]);
		expect(records).toHaveLength(2);
		expect(records[0]).toMatchObject({ kind: "assistant", streaming: true, text: "" });
		expect(records[1]).toMatchObject({ kind: "user" });
	});

	it("an unknown relay kind feeds NOTHING rather than inventing a row", () => {
		/*
		 * THE `default -> null` ARM, which round 1 never reached: the test above it
		 * only exercised kinds that HAVE an arm (C1-m5). A bundle newer than this
		 * client can send a kind this map does not know, and the rule is that it
		 * contributes no record at all - never a placeholder row, which would paint
		 * an empty line the reader cannot dismiss.
		 */
		const unknown = { ...entry({ id: "u-new" }), kind: "some_future_kind" } as unknown as TranscriptEntry;
		expect(toCondenseRecords([unknown])).toEqual([]);
		/* And it does not disturb its neighbours. */
		const mixed = toCondenseRecords([entry({ id: "u1", kind: "user" }), unknown, entry({ id: "a1" })]);
		expect(mixed.map((record) => record.id)).toEqual(["u1", "a1"]);
	});
});

/*
 * ------------------------- THE WIRE-LEVEL REPLAY -------------------------
 *
 * WHY THIS EXISTS BESIDE THE RECORD REPLAY (round 1, C1-m3). The replay above
 * asks the PORTED MODEL the desktop's question over desktop-vocabulary records -
 * which is what makes it comparable to the fixture. It therefore skips this
 * surface's one relay-specific layer, `toCondenseRecords`, which had six unit
 * tests and no parity coverage: mapper drift would leave the model replay green
 * and the phone wrong. Here every expressible case is built as the WIRE ROWS the
 * projector actually emits, pushed through the mapper, and compared to the same
 * expectation. `Z`/`R` are absent because the projector never mints that row.
 */
type WireToken = (id: string, i: number) => TranscriptEntry;

const wireEntry = (over: Partial<TranscriptEntry>): TranscriptEntry =>
	({
		id: "e",
		kind: "assistant",
		text: "",
		tool_call_id: "",
		tool_name: "",
		tool_state: "done",
		summary: "",
		intent: "",
		diff_added: 0,
		diff_removed: 0,
		elapsed_s: 0,
		error: "",
		details: {},
		final: true,
		...over,
	}) as TranscriptEntry;

const wireTool = (toolName: string, over: Partial<TranscriptEntry> = {}): TranscriptEntry =>
	wireEntry({ kind: "tool", tool_name: toolName, tool_call_id: String(over.id ?? toolName), ...over });

/**
 * THE WIRE ROWS FOR EACH TOKEN, built the way the PROJECTOR builds them:
 * the four condensation facts (`stop_reason`, `calls_tools`, `custom_type`,
 * `terminal`) are the only channels a fact has, so this table is a second reading
 * of the same mapping the desktop's token grammar encodes.
 */
const WIRE: Record<string, WireToken> = {
	U: (id) => wireEntry({ id, kind: "user", text: "hi" }),
	T: (id) => wireTool("bash", { id }),
	Rd: (id) => wireTool("read", { id }),
	Wr: (id) => wireTool("write", { id }),
	Sr: (id) => wireTool("web_fetch", { id }),
	Wb: (id) => wireTool("web_search", { id }),
	Mc: (id) => wireTool("mcp__datadog_search_datadog_metrics", { id }),
	Ag: (id) => wireTool("task", { id }),
	Py: (id) => wireTool("eval", { id }),
	Ak: (id) => wireTool("agent", { id }),
	Td: (id) => wireTool("todo", { id }),
	Fa: (id) => wireTool("bash", { id, tool_state: "failed" }),
	Du: (id) => wireTool("bash", { id, elapsed_s: 7 }),
	N: (id) => wireEntry({ id, kind: "assistant", text: "text", calls_tools: true }),
	F: (id) => wireEntry({ id, kind: "assistant", text: "text" }),
	A: (id) => wireEntry({ id, kind: "assistant", text: "text", stop_reason: "stop" }),
	L: (id) =>
		wireEntry({ id, kind: "assistant", text: "text", stop_reason: "toolUse", calls_tools: true }),
	S: (id) => wireEntry({ id, kind: "assistant", text: "text", final: false }),
	E: (id) => wireEntry({ id, kind: "assistant", text: "", calls_tools: true }),
	W: (id) => wireEntry({ id, kind: "notice", text: "wake", custom_type: "wake_prompt" }),
	P: (id) =>
		wireEntry({ id, kind: "peer_message", text: "peer", details: { sender: {} } }),
	J: (id) => wireEntry({ id, kind: "notice", text: "t", custom_type: "job_result" }),
	H: (id) => wireEntry({ id, kind: "notice", text: "t", custom_type: "hub_message" }),
	X: (id) => wireEntry({ id, kind: "notice", text: "t", custom_type: "monitor_prompt" }),
	Q: (id) =>
		wireEntry({ id, kind: "notice", text: "t", custom_type: "session_mcp_unavailable" }),
	I: (id) => wireEntry({ id, kind: "notice", text: "t", custom_type: "session_incident" }),
	M: (id) =>
		wireEntry({ id, kind: "notice", text: "n", details: { severity: "error" }, terminal: true }),
	K: (id) => wireEntry({ id, kind: "notice", text: "n", terminal: true }),
	O: (id) => wireEntry({ id, kind: "notice", text: "n" }),
	C: (id) => wireEntry({ id, kind: "compaction", text: "Context" }),
};

/** The wire rows for one token line, through the mapper. */
const seqWire = (spec: string): CondenseRecord[] =>
	toCondenseRecords(
		spec
			.trim()
			.split(/\s+/)
			.map((token, index) => WIRE[token](`${token}${index}`, index)),
	);

/**
 * IDS COMPARED MODULO THE DOCUMENTED CALL KEY.
 *
 * The fixture's ids are the desktop's record ids; this surface deliberately keys a
 * tool row by its CALL id (`rowKey`, gap G9), so the same row is `T1` there and
 * `call:T1` here. That difference is the mapping's stated design, not a decision,
 * so the comparison strips the prefix on both sides - INCLUDING inside a segment key
 * (`qg:call:T1` vs `qg:T1`), which is where it hides once a span names its own
 * first row. The replay still exercises `rowKey`: a mapper that lost it would
 * produce `T1` throughout and pass, which is what the six mapper unit tests own.
 */
const CALL_KEY = "call:";

const normalizeIds = (value: unknown): unknown => {
	if (typeof value === "string") return value.split(CALL_KEY).join("");
	if (Array.isArray(value)) return value.map(normalizeIds);
	if (typeof value === "object" && value !== null)
		return Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, normalizeIds(inner)]));
	return value;
};

describe("every expressible case, replayed through the WIRE mapper", () => {
	for (const entry of FIXTURE.cases.filter((candidate) => !skipped(candidate)))
		it(`${entry.tokens} [${entry.options}]`, () => {

			expect(normalizeIds(decide(seqWire(entry.tokens), entry.options))).toEqual(
				normalizeIds(entry.expected),
			);
		});
});

/*
 * ------------------- THE QUIET-CLOSED FALLBACK, PINNED -------------------
 *
 * The skip-list says a quiet-closed run "reads as Steered" here. That is a claim
 * about this surface's decisions, so it is asserted rather than described (round
 * 1, C1-m2): the quiet call's row never arrives, so the exchange before it cannot
 * close on it, and the user row that follows becomes a STEER inside the same run
 * instead of a new turn's opener.
 */
describe("the quiet-closed fallback the skip-list names", () => {
	/*
	 * WHAT THE GAP ACTUALLY IS, measured rather than described. A quiet `no_reply`
	 * call is a CLOSE on the desktop: it ends the turn, so the next user row opens a
	 * NEW run. This wire never mints that row, so the close never lands and the two
	 * user turns stay in ONE run - the first turn's rows condense only when the
	 * merged run settles, and the second prompt reads as a steer inside it.
	 *
	 * (Round 1's claim - "its bar is labelled `Steered`" - was wrong: the bar over
	 * the first turn's work is the run's own, and a user row is PINNED (V3), so no
	 * segment is labelled for it. The run SPLIT is the difference, and it is what
	 * this test asserts.)
	 */
	it("the turn does not split where the desktop's quiet close would end it", () => {
		const planOf = (records: CondenseRecord[]) =>
			collapsePlan(buildRows(records, []), {
				live: false,
				mode: "by-turn",
				olderRowsExist: false,
			});
		/* Desktop shape: the settled `no_reply` close ends the turn - two runs. */
		const desktop = planOf(seq("U T Z U A"));
		/* This surface: no such row exists, so one run holds both prompts. */
		const wire = planOf(seq("U T U A"));
		expect(desktop.runs.length).toBe(2);
		expect(wire.runs.length).toBe(1);
		/* And the settled merged run still condenses: the first turn's work is not
		 * lost, only deferred to the merged run's settlement. */
		expect(wire.runs[0].segments.length).toBeGreaterThan(0);
	});
});
